('coc1_m1', 'Identify Computer Parts and Tools — simulation assessment', '[{"criterion_code":"COC1_M1_S1","title":"Inspect hardware","description":"Inspect each component and its visible condition.","source_trace":"LO1.1 Assemble computer hardware · PC 1.1, 1.2, 1.3 · TR Computer Systems Servicing NC II (Amended December 2013); ByteQuest supplementary simulation assessment, not an official TESDA certification.","evidence_rule":{"operator":"simulation_condition","phase_ids":["coc1_m1_p1"],"conditions":[{"path":"inspected.motherboard","value":true},{"path":"inspected.cpu","value":true},{"path":"inspected.ram","value":true},{"path":"inspected.psu","value":true},{"path":"inspected.cpu_socket","value":true},{"path":"inspected.dimm_slot","value":true},{"path":"inspected.atx_power_port","value":true}],"counted_targets":["phase:coc1_m1_p1"],"max_incorrect":2},"scoring_rule":{"status":"APPROVED","method":"binary","satisfied_value":1,"not_satisfied_value":0,"classification":"TECHNICAL_BINARY_ENCODING","note":"1/0 encodes SATISFIED/NOT SATISFIED only; it is not a TESDA percentage or criterion weight."},"max_value":1,"order_index":1,"is_required":true},{"criterion_code":"COC1_M1_S2","title":"Select a safe set","description":"Record the components and safety equipment needed for the work.","source_trace":"LO1.1 Assemble computer hardware · PC 1.1, 1.2, 1.3 · TR Computer Systems Servicing NC II (Amended December 2013); ByteQuest supplementary simulation assessment, not an official TESDA certification.","evidence_rule":{"operator":"simulation_condition","phase_ids":["coc1_m1_p2"],"conditions":[{"path":"selection.coc1_m1_p2","operator":"present"},{"path":"classification.processing","operator":"present"},{"path":"classification.memory","operator":"present"},{"path":"classification.power","operator":"present"},{"path":"tool.chassis_ground","value":"anti_static_strap"},{"path":"tool.case_fastener","value":"screwdriver"}],"counted_targets":["phase:coc1_m1_p2","tool:chassis_ground","too