-- Rollback-only: every simulation assessment the publish script creates can be
-- passed (re-defense slice A1, fix round 1, review finding C1).
--
-- For each of the 20 missions the package is published the way
-- scripts/publish-simulation-assessments.mjs publishes it: an assessment
-- activity whose evaluator holds the mission's practice contract, the
-- script's step criteria (simulation_condition rules, generated below) and
-- an approved binary_sum / all_required rubric, all through the governed
-- RPCs. A learner then submits the mission's exported happy path - the
-- evidence the assessment-mode screen records for a correct run, which
-- test/assessment_mode_test.dart drives through the real controls - through
-- start_attempt, append_attempt_action and submit_attempt. Every criterion
-- must be satisfied and every attempt competent.
--
-- Regenerate the GENERATED blocks when the criteria rules or a contract
-- change: export {mission_id: {version, definition}, __links} from
-- practice_mission_contracts and mission_curriculum_links, run
-- buildSimulationPackage from the publish script for each mission, and
-- export the happy paths with
--   dart run tool/export_practice_contracts.dart --replay-fixtures <file>
begin;
select plan(24);

create temp table all_ctx (
  admin uuid not null default gen_random_uuid(),
  instructor uuid not null default gen_random_uuid(),
  learner uuid not null default gen_random_uuid(),
  source uuid, class uuid
) on commit drop;
select '00000000-0000-0000-0000-000000000000'::uuid, id, 'authenticated', 'authenticated',
  'simulation-all-' || id || '@bytequest.invalid', '', '{"provider":"email","providers":["email"]}'::jsonb,
  '{"full_name":"Simulation assessment rollback fixture"}'::jsonb, now(), now()
from all_ctx cross join lateral (values (admin), (instructor), (learner)) u(id);
update public.profiles set role = 'admin' where user_id = (select admin from all_ctx);
update public.profiles set role = 'instructor' where user_id = (select instructor from all_ctx);

-- BEGIN GENERATED CRITERIA (publish-simulation-assessments.mjs buildSimulationPackage)
create temp table all_package(mission_code text primary key, title text not null, criteria jsonb not null,
  module_version uuid, activity uuid, rubric uuid, assignment uuid, attempt uuid) on commit drop;
-- END GENERATED CRITERIA

-- BEGIN GENERATED HAPPY PATHS (tool/export_practice_contracts.dart --replay-fixtures)
create temp table replay_fixture(mission_id text, ordinal integer, phase_id text, action_type text,
  target text, value jsonb) on commit drop;
-- Generated by tool/export_practice_contracts.dart --replay-fixtures.
-- END GENERATED HAPPY PATHS

with s as (
    validation_notes, created_by, approved_by, approved_at, activated_by, activated_at)
  select 'ROLLBACK-' || left(gen_random_uuid()::text, 8), 'Rollback-only simulation assessment source',
    'TEST_ONLY', 'Rollback fixture; never a production TESDA source', 'active', 'TEST_ONLY_ROLLBACK_FIXTURE',
    admin, admin, now(), admin, now() from all_ctx
  returning id)
update all_ctx set source = s.id from s;

-- One draft module version per COC and one draft assessment activity per
-- mission, shaped as the publish script writes them.
create temp table all_module(coc_code text primary key, module_version uuid) on commit drop;
with m as (
    content_metadata, status, created_by)
  select c.id, x.source, coalesce((select max(version_number) from public.module_versions mv where mv.module_id = c.id), 0) + 1,
    upper(c.coc_code) || ' simulation assessments',
    jsonb_build_object('source_classification', 'TEST_ONLY', 'note', 'Rollback fixture'),
    jsonb_build_object('assessment_engine', 'simulation_replay_v1'), 'draft', x.admin
  from all_ctx x cross join public.coc_modules c
  returning id, module_id)

do $$
declare p record; v_activity uuid;
begin
  for p in select mission_code, title from all_package order by mission_code loop
      learner_payload, evaluator_config, status, created_by)
    select ms.id, am.module_version,
      coalesce((select max(version_number) from public.activity_versions v where v.mission_id = ms.id), 0) + 1,
      p.title, 'assessment',
      jsonb_build_object('mission_id', ms.mission_code, 'definition_version', c.version, 'mode', 'assessment'),
      jsonb_build_object('engine', 'simulation_replay_v1', 'simulation_definition', c.definition,
        'contract_version', c.version, 'scoring_method', 'binary_sum', 'competency_method', 'all_required',
        'client_score_authoritative', false),
      'draft', (select admin from all_ctx)
    from public.missions ms
    join public.practice_mission_contracts c on c.mission_id = ms.mission_code
    join all_module am on am.coc_code = left(ms.mission_code, 4)
    where ms.mission_code = p.mission_code
    returning id into v_activity;
    update all_package set activity = v_activity where mission_code = p.mission_code;
    values (v_activity, (select source from all_ctx), 1, upper(p.mission_code) || ' simulation step rubric', 'draft',
      (select admin from all_ctx));
    update all_package set rubric = (select id from public.rubric_versions where activity_version_id = v_activity)
      where mission_code = p.mission_code;
  end loop;
end $$;

  evidence_rule, scoring_rule, max_value, order_index, is_required)
select p.rubric, c->>'criterion_code', c->>'title', c->>'description', c->>'source_trace',
  c->'evidence_rule', c->'scoring_rule', (c->>'max_value')::numeric, (c->>'order_index')::integer,
  (c->>'is_required')::boolean
from all_package p, jsonb_array_elements(p.criteria) c;

select p.activity, l.module_id, 'simulation'
from all_package p join public.mission_curriculum_links l on l.mission_code = p.mission_code;

-- The admin publishes every module and activity and approves every rubric
-- through the governed RPCs; approval validates every generated rule.
create temp table all_failure(step text, error text) on commit drop;
grant select on all_ctx, all_package, all_module to authenticated;
grant insert on all_failure to authenticated;
select set_config('request.jwt.claim.sub', (select admin::text from all_ctx), true);
select set_config('request.jwt.claim.role', 'authenticated', true);
set local role authenticated;
do $$
declare r record;
begin
  for r in select module_version from all_module loop
    begin
      perform public.publish_module_version(r.module_version, 'Rollback publication of the simulation assessment module');
    exception when others then
    end;
  end loop;
  for r in select mission_code, activity, rubric from all_package order by mission_code loop
    begin
      perform public.publish_activity_version(r.activity, 'Rollback publication of the ' || r.mission_code || ' simulation assessment');
      perform public.approve_rubric_version(r.rubric, 'binary_sum',
        jsonb_build_object('status', 'APPROVED', 'method', 'all_required',
          'classification', 'PROJECT_APPROVED_OPERATIONAL_RULE', 'official_numeric_threshold', null,
          'step_threshold', 'At most two incorrect attempts per step; safety-critical steps none (owner decision 7).'),
        'Rollback approval of the generated simulation step rubric');
    exception when others then
    end;
  end loop;
end $$;
reset role;
select is((select coalesce(string_agg(step || ': ' || error, '; '), 'none') from all_failure), 'none',
  'every generated package publishes and its rubric passes governed approval');

with c as (
  select 'Rollback simulation assessment class', instructor, instructor from all_ctx returning id)
update all_ctx set class = c.id from c;
select class, learner, instructor from all_ctx;
do $$
declare p record; v_assignment uuid;
begin
  for p in select mission_code, activity, rubric from all_package order by mission_code loop
    select class, p.activity, p.rubric, 'assessment', upper(p.mission_code) || ' simulation assessment', instructor
    from all_ctx returning id into v_assignment;
    update all_package set assignment = v_assignment where mission_code = p.mission_code;
  end loop;
end $$;

-- The learner submits each mission's correct run through the normal RPCs.
grant select, update on all_package to authenticated;
grant select on replay_fixture to authenticated;
select set_config('request.jwt.claim.sub', (select learner::text from all_ctx), true);
select set_config('request.jwt.claim.role', 'authenticated', true);
set local role authenticated;
do $$
declare p record; v_attempt uuid; f record;
begin
  for p in select mission_code, assignment from all_package order by mission_code loop
    select id into v_attempt from public.start_attempt(p.assignment, gen_random_uuid());
    for f in select * from replay_fixture where mission_id = p.mission_code order by ordinal loop
      perform public.append_attempt_action(v_attempt, f.ordinal, f.action_type, f.target,
        f.value || jsonb_build_object('phase_id', f.phase_id, 'mission_id', f.mission_id,
          'runtime_action_type', coalesce(f.value->>'runtime_action_type', f.action_type),
          'client_action_id', p.mission_code || '-' || f.ordinal),
        clock_timestamp());
    end loop;
    perform public.submit_attempt(v_attempt, gen_random_uuid(), 900);
    update all_package set attempt = v_attempt where mission_code = p.mission_code;
  end loop;
end $$;
reset role;

create function pg_temp.not_satisfied(p_mission text)
returns text language sql stable as $$
  select coalesce(string_agg(rc.criterion_code || ' ' || cr.observed_evidence::text, '; ' order by rc.order_index), 'none')
  from public.criterion_results cr
  join public.rubric_criteria rc on rc.id = cr.rubric_criterion_id
  where cr.attempt_id = (select attempt from all_package where mission_code = p_mission)
    and cr.observation <> 'satisfied'
$$;

select is(pg_temp.not_satisfied(mission_code), 'none',
  mission_code || ': a correct assessment run satisfies every step criterion')
from all_package order by mission_code;
select is((select count(*)::integer from public.criterion_results
    where attempt_id in (select attempt from all_package)),
  (select sum(jsonb_array_length(criteria))::integer from all_package),
  'every generated criterion is evaluated');
select is((select count(*)::integer from public.score_revisions
    where attempt_id in (select attempt from all_package)
      and revision_type = 'automated_provisional' and outcome = 'competent'),
  20, 'every correct assessment run is competent');
select is((select count(*)::integer from public.activity_versions
    where id in (select activity from all_package) and not (learner_payload ? 'simulation_template')),
  20, 'every learner payload opens the shared simulation, not a form template');

select * from finish();
rollback;
